    final WorkerTopologyContext context = mock(WorkerTopologyContext.class);
    // Call prepare with our available taskIds
    grouper.prepare(context, null, availableTaskIds);
    List<Callable<int[]>> threadTasks = Lists.newArrayList();
    for (int x = 0; x < numThreads; x++) {
        Callable<int[]> threadTask = () -> {
            int[] taskCounts = new int[availableTaskIds.size()];
            for (int i = 1; i <= groupingExecutionsPerThread; i++) {
                List<Integer> taskIds = grouper.chooseTasks(inputTaskId, Lists.newArrayList());
                // Validate a single task id return
                assertNotNull(taskIds, "Not null taskId list returned");
                assertEquals(1, taskIds.size(), "Single task Id not returned");
                int taskId = taskIds.get(0);
                assertTrue(taskId >= 0 && taskId < availableTaskIds.size(), "TaskId should exist");
                taskCounts[taskId]++;
            }
            return taskCounts;
        };
        // Add to our collection.
        threadTasks.add(threadTask);
    }
    ExecutorService executor = Executors.newFixedThreadPool(threadTasks.size());
    List<Future<int[]>> taskResults = executor.invokeAll(threadTasks);
    // Wait for all tasks to complete
    int[] taskIdTotals = new int[numTasks];
    for (Future<int[]> taskResult : taskResults) {
        while (!taskResult.isDone()) {
            Thread.sleep(1000);
        }
        int[] taskDistributions = taskResult.get();
        for (int i = 0; i < taskDistributions.length; i++) {
            taskIdTotals[i] += taskDistributions[i];
        }
    }
    for (int i = 0; i < numTasks; i++) {
        assertEquals(numThreads * groupingExecutionsPerThread / numTasks, taskIdTotals[i]);
    }
}

@Test
public void spoutMustIgnoreFailsForTuplesItIsNotAssignedAfterRebalance() {
    //Failing tuples for partitions that are no longer assigned is useless since the spout will not be allowed to commit them if they later pass
    TopicAssigner assignerMock = mock(TopicAssigner.class);
    KafkaSpoutRetryService retryServiceMock = mock(KafkaSpoutRetryService.class);
    KafkaSpout<String, String> spout = new KafkaSpout<>(createKafkaSpoutConfigBuilder(topicFilterMock, partitionerMock, -1).setOffsetCommitPeriodMs(10).setRetry(retryServiceMock).build(), clientFactory, assignerMock);
    String topic = SingleTopicKafkaSpoutConfiguration.TOPIC;
    TopicPartition partitionThatWillBeRevoked = new TopicPartition(topic, 1);
    TopicPartition assignedPartition = new TopicPartition(topic, 2);
    when(retryServiceMock.getMessageId(any(TopicPartition.class), anyLong())).thenReturn(new KafkaSpoutMessageId(partitionThatWillBeRevoked, 0)).thenReturn(new KafkaSpoutMessageId(assignedPartition, 0));
    //Emit a message on each partition and revoke the first partition
    List<KafkaSpoutMessageId> emittedMessageIds = emitOneMessagePerPartitionThenRevokeOnePartition(spout, partitionThatWillBeRevoked, assignedPartition, assignerMock);
    //Check that only two message ids were generated
    verify(retryServiceMock, times(2)).getMessageId(any(TopicPartition.class), anyLong());
    //Fail both emitted tuples
    spout.fail(emittedMessageIds.get(0));
    spout.fail(emittedMessageIds.get(1));
    //Check that only the tuple on the currently assigned partition is retried
    verify(retryServiceMock, never()).schedule(emittedMessageIds.get(0));
    verify(retryServiceMock).schedule(emittedMessageIds.get(1));
}

